4	unsafe fn test_nofollow_errors(dir_fd: wasi::Fd) {
5	    // Create a directory for the symlink to point to.
6	    wasi::path_create_directory(dir_fd, "target").expect("creating a dir");
7	
8	    // Create a symlink.
9	    wasi::path_symlink("target", dir_fd, "symlink").expect("creating a symlink");
10	
11	    // Try to open it as a directory with O_NOFOLLOW again.
12	    assert_errno!(
13	        wasi::path_open(dir_fd, 0, "symlink", wasi::OFLAGS_DIRECTORY, 0, 0, 0)
14	            .expect_err("opening a directory symlink as a directory should fail"),
15	        wasi::ERRNO_LOOP,
16	        wasi::ERRNO_NOTDIR
17	    );
18	
19	    // Try to open it with just O_NOFOLLOW.
20	    assert_errno!(
21	        wasi::path_open(dir_fd, 0, "symlink", 0, 0, 0, 0)
22	            .expect_err("opening a symlink with O_NOFOLLOW should fail"),
23	        wasi::ERRNO_LOOP,
24	        wasi::ERRNO_ACCES
25	    );
26	
27	    // Try to open it as a directory without O_NOFOLLOW.
28	    let file_fd = wasi::path_open(
29	        dir_fd,
30	        wasi::LOOKUPFLAGS_SYMLINK_FOLLOW,
31	        "symlink",
32	        wasi::OFLAGS_DIRECTORY,
33	        0,
34	        0,
35	        0,
36	    )
37	    .expect("opening a symlink as a directory");
38	    assert!(
39	        file_fd > libc::STDERR_FILENO as wasi::Fd,
40	        "file descriptor range check",
41	    );
42	    wasi::fd_close(file_fd).expect("closing a file");
43	
44	    // Replace the target directory with a file.
45	    wasi::path_unlink_file(dir_fd, "symlink").expect("removing a file");
46	    wasi::path_remove_directory(dir_fd, "target")
47	        .expect("remove_directory on a directory should succeed");
48	
49	    let file_fd =
50	        wasi::path_open(dir_fd, 0, "target", wasi::OFLAGS_CREAT, 0, 0, 0).expect("creating a file");
51	    wasi::fd_close(file_fd).expect("closing a file");
52	    wasi::path_symlink("target", dir_fd, "symlink").expect("creating a symlink");
53	
54	    // Try to open it as a directory with O_NOFOLLOW again.
55	    assert_errno!(
56	        wasi::path_open(dir_fd, 0, "symlink", wasi::OFLAGS_DIRECTORY, 0, 0, 0)
57	            .expect_err("opening a directory symlink as a directory should fail"),
58	        wasi::ERRNO_LOOP,
59	        wasi::ERRNO_NOTDIR
60	    );
61	
62	    // Try to open it with just O_NOFOLLOW.
63	    assert_errno!(
64	        wasi::path_open(dir_fd, 0, "symlink", 0, 0, 0, 0)
65	            .expect_err("opening a symlink with NOFOLLOW should fail"),
66	        wasi::ERRNO_LOOP
67	    );
68	
69	    // Try to open it as a directory without O_NOFOLLOW.
70	    assert_errno!(
71	        wasi::path_open(
72	            dir_fd,
73	            wasi::LOOKUPFLAGS_SYMLINK_FOLLOW,
74	            "symlink",
75	            wasi::OFLAGS_DIRECTORY,
76	            0,
77	            0,
78	            0,
79	        )
80	        .expect_err("opening a symlink to a file as a directory"),
81	        wasi::ERRNO_NOTDIR
82	    );
83	
84	    // Clean up.
85	    wasi::path_unlink_file(dir_fd, "target").expect("removing a file");
86	    wasi::path_unlink_file(dir_fd, "symlink").expect("removing a file");
87	}
