527	        let mut create = false;
528	        // Track open mode, for permission check and recording in created descriptor:
529	        let mut open_mode = OpenMode::empty();
530	        // Construct the OpenOptions to give the OS:
531	        let mut opts = cap_std::fs::OpenOptions::new();
532	        opts.maybe_dir(true);
533	
534	        if oflags.contains(OpenFlags::CREATE) {
535	            if oflags.contains(OpenFlags::EXCLUSIVE) {
536	                opts.create_new(true);
537	            } else {
538	                opts.create(true);
539	            }
540	            create = true;
541	            opts.write(true);
542	            open_mode |= OpenMode::WRITE;
543	        }
544	
545	        if oflags.contains(OpenFlags::TRUNCATE) {
546	            opts.truncate(true).write(true);
547	        }
548	        if flags.contains(DescriptorFlags::READ) {
549	            opts.read(true);
550	            open_mode |= OpenMode::READ;
551	        }
552	        if flags.contains(DescriptorFlags::WRITE) {
553	            opts.write(true);
554	            open_mode |= OpenMode::WRITE;
555	        } else {
556	            // If not opened write, open read. This way the OS lets us open
557	            // the file, but we can use perms to reject use of the file later.
558	            opts.read(true);
