    let stream = file.read_via_stream(0).expect("read stream");
    let ready = stream.subscribe();
    loop {
        ready.block();
        match stream.read(128) {
            Ok(chunk) => contents.extend(chunk),
            Err(wasi::io::streams::StreamError::Closed) => break,
            Err(e) => panic!("failed reading file: {e:?}"),
        }
    }
    contents
}

