    let (dir, _) = preopens
        .iter()
        .find(|(_, name)| name == "readonly")
        .expect("locating the 'readonly' preopened directory");

    // The file should start out with the expected contents.
    assert_eq!(
        read_file_contents(dir),
        EXPECTED,
        "file contents before attempted truncation"
    );

    // Attempting to open the file with the truncation flag but only the read
    // flag should be rejected with a permission error, because truncation
    // implies a write operation.
    let err = dir
        .open_at(
            PathFlags::empty(),
            FILENAME,
            OpenFlags::TRUNCATE,
            DescriptorFlags::READ,
        )
        .expect_err("opening a read-only file with the truncation flag should fail");
    assert_eq!(err, ErrorCode::NotPermitted);

    // The file contents must be unchanged: no truncation occurred.
    assert_eq!(
        read_file_contents(dir),
        EXPECTED,
        "file contents after attempted truncation"
    );
}
