    let ctx = Ctx {
        table: ResourceTable::new(),
        wasi: builder.build(),
    };
    let mut store = Store::new(&engine, ctx);

    let component = Component::from_file(&engine, component_path)?;
    let mut linker = Linker::new(&engine);
    wasmtime_wasi::add_to_linker_async(&mut linker)?;
    let command = wasmtime_wasi::bindings::Command::instantiate_async(
        &mut store, &component, &linker,
    )
    .await?;

    let result = command.wasi_cli_run().call_run(&mut store).await?;
    result.map_err(|()| anyhow::anyhow!("guest returned error"))?;

    // Confirm the host file was NOT truncated.
    let after = std::fs::read(dir.path().join("test.txt"))?;
    assert_eq!(after, b"truncation test file\n");
    println!("OK: {component_path} passed, file intact");
    Ok(())
}

