    tokio::runtime::Runtime::new()?.block_on(async {
        run(test_programs_artifacts::PREVIEW2_FILE_TRUNCATION_READONLY_COMPONENT).await?;
        run(test_programs_artifacts::PREVIEW1_FILE_TRUNCATION_READONLY_COMPONENT).await?;
        Ok(())
    })
}
